54	// This file defines a set of base classes for building XLS compiler passes and
55	// pass pipelines. The base classes are templated allowing polymorphism of the
56	// data types the pass operates on.
57	
58	// Options data structure passed to each pass run invocation. This data
59	// structure is passed by const reference to PassBase::Run and should contain
60	// options which affect how passes are run.
61	struct PassOptionsBase {
62	  // If non-empty, this is the path to the directory in which to dump
63	  // intermediate IR files.
64	  std::filesystem::path ir_dump_path;
65	
66	  // If present, passes whose short names are in this list will be skipped. If
67	  // both run_only_passes and skip_passes are present, then only passes which
68	  // are present in run_only_passes and not present in skip_passes will be run.
69	  std::vector<std::string> skip_passes;
70	
71	  // If present, how many passes will be allowed to run to completion. NB
72	  // Passes which do not cause any changes are counted in this limit. When this
73	  // limit is reached all subsequent passes perform no changes. NB The total
74	  // number of passes executed might change due to setting this field as
75	  // fixed-points may complete earlier.
76	  std::optional<int64_t> bisect_limit;
77	};
78	
79	class PassResults;
80	
81	enum class SkipReason {
82	  kKnownRedundant,
83	  kBisectLimit,
84	  kSkipPasses,
85	};
