87	// An object containing information about the invocation of a pass (single call
88	// to PassBase::Run).
89	class PassInvocation {
90	 public:
91	  explicit PassInvocation(PassInvocation* parent, std::string_view pass_name,
92	                          int64_t pass_number)
93	      : pass_name_(pass_name), pass_numbers_({pass_number}), parent_(parent) {}
94	  PassInvocation(const PassInvocation&) = delete;
95	  PassInvocation& operator=(const PassInvocation&) = delete;
96	  PassInvocation(PassInvocation&&) = default;
97	  PassInvocation& operator=(PassInvocation&&) = default;
98	
99	  bool is_root() const { return parent_ == nullptr; }
100	  TransformMetrics& metrics() { return metrics_; }
101	  const TransformMetrics& metrics() const { return metrics_; }
102	  const absl::Duration& run_duration() const { return run_duration_; }
103	  absl::Duration& run_duration() { return run_duration_; }
104	  std::string_view pass_name() const { return pass_name_; }
105	  bool ir_changed() const { return ir_changed_; }
106	  std::optional<SkipReason> skip_reason() const { return skip_reason_; }
107	  int64_t fixed_point_iterations() const { return fixed_point_iterations_; }
108	  absl::Span<int64_t const> all_pass_numbers() const { return pass_numbers_; }
109	  // The initial pass number.
110	  int64_t pass_number() const { return pass_numbers_.front(); }
111	  void set_ir_changed(bool ir_changed) { ir_changed_ = ir_changed; }
112	  void set_skipped(SkipReason reason) { skip_reason_ = reason; }
113	  void IncrementFixedPointIterations() { fixed_point_iterations_++; }
114	  PassInvocation& parent() {
115	    CHECK(!is_root()) << "Attempting to get parent of root invocation.";
116	    return *parent_;
117	  }
118	  const PassInvocation& parent() const {
119	    CHECK(!is_root()) << "Attempting to get parent of root invocation.";
120	    return *parent_;
121	  }
122	  absl::Span<const std::unique_ptr<PassInvocation>> nested_invocations() const {
123	    return nested_invocations_;
124	  }
125	
126	 private:
127	  // The short name of the pass.
128	  std::string pass_name_;
129	
130	  // Whether the IR was changed by the pass.
131	  bool ir_changed_ = false;
132	
133	  // Whether the pass was skipped.
134	  std::optional<SkipReason> skip_reason_ = std::nullopt;
135	
136	  // The run duration of the pass.
137	  absl::Duration run_duration_;
138	
139	  // Number of nodes added, removed, etc.
140	  TransformMetrics metrics_;
141	
142	  // For compound passes, this holds the invocation data for the nested passes.
143	  std::vector<std::unique_ptr<PassInvocation>> nested_invocations_;
144	
145	  // For fixed point compound passes this is the number of iterations of the
146	  // pass.
147	  int64_t fixed_point_iterations_ = 0;
148	
149	  // How many passes ran before this pass started. Fixedpoint will have
150	  // multiple.
151	  std::vector<int64_t> pass_numbers_;
152	
153	  PassInvocation* parent_ = nullptr;
154	
155	  friend class PassResults;
156	};
