164	// A object to which metadata may be written in each pass invocation. This data
165	// structure is passed by mutable pointer to PassBase::Run.
166	class PassResults {
167	 public:
168	  PassResults()
169	      : root_invocation_(std::make_unique<PassInvocation>(nullptr, "root", -1)),
170	        latest_(root_invocation_.get()) {};
171	  PassResults(const PassResults&) = delete;
172	  PassResults& operator=(const PassResults&) = delete;
173	  PassResults(PassResults&&) = default;
174	  PassResults& operator=(PassResults&&) = default;
175	
176	  // Return the current invocation.
177	  PassInvocation& current_invocation() { return *latest_; }
178	
179	  PassInvocation& PushInvocation(std::string_view pass_name) {
180	    total_invocations_++;
181	    latest_ = latest_->nested_invocations_
182	                  .emplace_back(std::make_unique<PassInvocation>(
183	                      latest_, pass_name, total_invocations_ - 1))
184	                  .get();
185	    return *latest_;
186	  }
187	  PassInvocation& PopInvocation() {
188	    CHECK(!latest_->is_root()) << "Attempting to pop the root invocation.";
189	    latest_ = &latest_->parent();
190	    finished_invocations_++;
191	    return *latest_;
192	  }
193	  void RestartCurrentInvocation() {
194	    CHECK(!latest_->is_root()) << "Attempting to restart the root invocation.";
195	    latest_->pass_numbers_.push_back(total_invocations_);
196	    latest_->fixed_point_iterations_++;
197	    total_invocations_++;
198	  }
199	
200	  PassPipelineMetricsProto ToProto() const;
201	  const PassInvocation& root_invocation() const { return *root_invocation_; }
202	  int64_t total_invocations() const { return total_invocations_; }
203	  int64_t finished_invocations() const { return finished_invocations_; }
204	
205	  bool IsKnownRedundant(std::string_view pass_signature) {
206	    return known_redundant_passes_.contains(pass_signature);
207	  }
208	  void AddKnownRedundantPass(std::string pass_signature) {
209	    known_redundant_passes_.insert(std::move(pass_signature));
210	  }
211	  void ClearKnownRedundantPasses() { known_redundant_passes_.clear(); }
212	
213	 private:
214	  // This vector contains and entry for each invocation of each pass.
215	  std::unique_ptr<PassInvocation> root_invocation_;
216	  PassInvocation* latest_;
217	
218	  // The total number of leaf-level (non-compound) pass invocations including
219	  // nested invocations.
220	  int64_t total_invocations_ = 0;
221	
222	  // The number of invocations which have finished. This is only tracked to
223	  // ensure that --ir_dump_path is numbered sequentially.
224	  // TODO(allight): We should probably just remove this and rethink the
225	  // numbering scheme of --ir_dump_path since it doesn't match with what
226	  // --passes_bisect_limit and other logging says the pass numbering is.
227	  int64_t finished_invocations_ = 0;
228	
229	  // Set of invocation signatures for passes that have been run and are known
230	  // to not change the IR since the last time the IR was changed.
231	  absl::flat_hash_set<std::string> known_redundant_passes_;
232	};
