237	// Defines if a pass can be skipped if it's shown to not transform IR.
238	class RedundancyGuard {
239	 public:
240	  // Never skip this pass due to redundancy.
241	  static RedundancyGuard Never() { return RedundancyGuard(NeverSkipT{}); }
242	
243	  // If IR is unchanged from the previous run of this pass that made no change,
244	  // then skip this pass. Full signature is just pass name.
245	  static RedundancyGuard CanSkip() { return RedundancyGuard(CanSkipT{}); }
246	
247	  // If IR is unchanged from the previous run of this pass with the same
248	  // `config` that made no change, then skip this pass. Full signature is
249	  // 'pass_name<config>'.
250	  static RedundancyGuard CanSkip(std::string config) {
251	    return RedundancyGuard(CanSkipT{.config = std::move(config)});
252	  }
253	
254	  // Get the signature to use for redundancy tracking.
255	  template <typename OptionsT, typename... ContextT>
256	  std::optional<std::string> GetSignature(
257	      const PassBase<OptionsT, ContextT...>* pass) const;
258	
259	 private:
260	  struct NeverSkipT : public std::monostate {};
261	  struct CanSkipT {
262	    std::optional<std::string> config;
263	  };
264	  using Condition = std::variant<NeverSkipT, CanSkipT>;
265	  explicit RedundancyGuard(Condition condition)
266	      : condition_(std::move(condition)) {}
267	  Condition condition_;
268	};
269	
270	struct PassInfo {
271	  std::string_view name;
272	  std::optional<std::string> redundancy_signature;
273	  bool is_idempotent = false;
274	};
