276	// RAII helper for holding pass invocation information. It holds and tracks pass
277	// results and also sets the various pprof tags for the pass.
278	class ScopedPassInvocation {
279	 public:
280	  ScopedPassInvocation(PassResults* results, PassInfo pass_info, Package* ir)
281	      : results_(results),
282	        invocation_(results->PushInvocation(pass_info.name)),
283	        pass_info_(std::move(pass_info)),
284	        ir_(ir),
285	        before_metrics_(ir->transform_metrics()) {
286	    RecordPassEntry(pass_info_.name);
287	    RecordPassAnnotation(pass_profile::kNodeCountBefore, ir->GetNodeCount());
288	  }
289	  ~ScopedPassInvocation() {
290	    invocation_.metrics() = (ir_->transform_metrics() - before_metrics_);
291	    invocation_.run_duration() = pass_stopwatch_.GetElapsedTime();
292	    VLOG(1) << absl::StreamFormat(
293	        "[elapsed %s] Pass %s %s.", FormatDuration(invocation_.run_duration()),
294	        invocation_.pass_name(),
295	        (invocation_.ir_changed() ? "changed IR" : "did not change IR"));
296	    if (invocation_.ir_changed()) {
297	      VLOG(1) << absl::StrFormat("Metrics: %s",
298	                                 invocation_.metrics().ToString());
299	      results_->ClearKnownRedundantPasses();
300	      if (pass_info_.is_idempotent &&
301	          pass_info_.redundancy_signature.has_value()) {
302	        results_->AddKnownRedundantPass(*pass_info_.redundancy_signature);
303	      }
304	    } else {
305	      if (pass_info_.redundancy_signature.has_value()) {
306	        results_->AddKnownRedundantPass(*pass_info_.redundancy_signature);
307	      }
308	    }
309	    RecordPassAnnotation(pass_profile::kNodeCountAfter, ir_->GetNodeCount());
310	    ExitPass(changed_);
311	    results_->PopInvocation();
312	  }
313	  PassResults* results() { return results_; }
314	  PassInvocation& invocation() { return invocation_; }
315	  const PassInvocation& invocation() const { return invocation_; }
316	  PassInvocation* operator->() { return &invocation_; }
317	  PassInvocation& operator*() { return invocation_; }
318	  void set_ir_changed(bool changed) {
319	    changed_ = changed;
320	    invocation_.set_ir_changed(changed);
321	  }
322	  void set_skipped(SkipReason reason) { invocation_.set_skipped(reason); }
323	  class ChangedRef {
324	   public:
325	    ChangedRef(ScopedPassInvocation& invocation, bool& changed)
326	        : invocation_(invocation), changed_(changed) {}
327	    operator bool() const { return changed_; }
328	    ChangedRef& operator=(bool other) {
329	      changed_ = other;
330	      invocation_.set_ir_changed(other);
331	      return *this;
332	    }
333	
334	   private:
335	    ScopedPassInvocation& invocation_;
336	    bool& changed_;
337	  };
338	  ChangedRef changed() { return ChangedRef(*this, changed_); }
339	
340	 private:
341	  PassResults* results_;
342	  PassInvocation& invocation_;
343	  PassInfo pass_info_;
344	  Package* ir_;
345	  bool changed_ = false;
346	  TransformMetrics before_metrics_;
347	  Stopwatch pass_stopwatch_;
348	};
349	
350	// A base class for abstractions which check invariants of the IR. These
351	// checkers are added to compound passes (pass pipelines) and run before and
352	// after each pass in the pipeline.
353	template <typename OptionsT, typename... ContextT>
354	class InvariantCheckerBase {
355	 public:
356	  virtual ~InvariantCheckerBase() = default;
357	  virtual absl::Status Run(Package* ir, const OptionsT& options,
358	                           PassResults* results,
359	                           ContextT&... context) const = 0;
360	};
361	template <typename OptionsT, typename... ContextT>
362	class WrapperPassBase;
363	
364	// Base class for all compiler passes. Template parameters:
365	//
366	//   OptionsT : Options type passed as an immutable object to each invocation of
367	//     PassBase::Run. This type should be derived from PassOptions because
368	//     PassOptions contains fields required by CompoundPassBase when executing
369	//     pass pipelines.
370	//
371	//   ContextT : A variable number of types (usually zero or one) which are
372	//     passed as mutable objects to each invocation of PassBase::Run. These
373	//     types are used to share non-IR information between passes (e.g., sharing
374	//     lazily-populated query engines across an optimization pipeline).
375	template <typename OptionsT, typename... ContextT>
376	class PassBase {
377	 public:
378	  using InvariantChecker = InvariantCheckerBase<OptionsT, ContextT...>;
379	
380	  PassBase(std::string_view short_name, std::string_view long_name)
381	      : short_name_(short_name), long_name_(long_name) {}
382	
383	  virtual ~PassBase() = default;
384	
385	  virtual std::string short_name() const { return short_name_; }
386	  // Get the short name of the underlying pass. Used to identify wrapper passes
387	  // and so on.
388	  virtual std::string_view base_short_name() const { return short_name_; }
389	  virtual std::string long_name() const { return long_name_; }
390	
391	  // Generate a proto that can be used to reconstitute this pass. By default is
392	  // 'short_name()'
393	  // TODO(allight): This is not very elegant. Ideally the registry could handle
394	  // this? Doing it there would probably be even more weird though.
395	  virtual absl::StatusOr<PassPipelineProto::Element> ToProto() const {
396	    if (IsCompound()) {
397	      return absl::UnimplementedError(
398	          "Compound pass without overriden ToProto.");
399	    }
400	    PassPipelineProto::Element res;
401	    *res.mutable_pass_name() = short_name_;
402	    return res;
403	  }
404	
405	  // Run the specific pass. Returns true if the graph was changed by the pass.
406	  // Typically the "changed" indicator is used to determine when to terminate
407	  // fixed point computation.
408	  //
409	  // This is the only entrypoint for a pass. It records invocation metrics and
410	  // the like and then calls RunInternal which must perform the actual pass.
411	  //
412	  // TODO(allight): We should change 'results' to a reference since it cannot
413	  // (and never really should) be null.
414	  absl::StatusOr<bool> Run(Package* ir, const OptionsT& options,
415	                           PassResults* results, ContextT&... context) const {
416	    XLS_RET_CHECK(results != nullptr) << "Results cannot be null";
417	    if (options.bisect_limit &&
418	        results->total_invocations() >= options.bisect_limit) {
419	      VLOG(1) << "Skipping pass " << short_name()
420	              << " due to hitting bisect limit.";
421	      return false;
422	    }
423	
424	    std::string_view base_short_name = this->base_short_name();
425	    if (std::find_if(options.skip_passes.begin(), options.skip_passes.end(),
426	                     [&](const std::string& name) {
427	                       return base_short_name == name;
428	                     }) != options.skip_passes.end()) {
429	      VLOG(1) << "Skipping pass \'" << this->short_name()
430	              << "\'. Contained in skip_passes option.";
431	      return false;
432	    }
433	
434	    std::optional<std::string> redundancy_signature =
435	        GetRedundancyGuard(options, context...).GetSignature(this);
436	
437	    ScopedPassInvocation invocation(
438	        results,
439	        PassInfo{
440	            .name = base_short_name,
441	            .redundancy_signature = redundancy_signature,
442	            .is_idempotent = IsIdempotent(),
443	        },
444	        ir);
445	    VLOG(2) << absl::StreamFormat("Running %s [pass #%d]", long_name(),
446	                                  invocation->pass_number());
447	    VLOG(3) << "Before:";
448	    XLS_VLOG_LINES(3, ir->DumpIr());
449	    int64_t ir_count_before = ir->GetNodeCount();
450	
451	#ifdef DEBUG
452	    // Verify that the IR should change iff Run returns true. This is slow, so
453	    // do not check it in optimized builds.
454	    std::string ir_before = ir->DumpIr();
455	#endif
456	    if (redundancy_signature.has_value() &&
457	        results->IsKnownRedundant(*redundancy_signature)) {
458	      VLOG(1) << "Skipping known-redundant pass: " << short_name();
459	      invocation.set_ir_changed(false);
460	      invocation.set_skipped(SkipReason::kKnownRedundant);
461	    } else {
462	      XLS_ASSIGN_OR_RETURN(
463	          invocation.changed(), RunInternal(ir, options, results, context...),
464	          _ << "Running pass #" << invocation->pass_number() << ": "
465	            << long_name() << " [short: " << short_name() << "]");
466	    }
467	    VLOG(3) << absl::StreamFormat("After [changed = %d]:",
468	                                  invocation.changed());
469	    XLS_VLOG_LINES(3, ir->DumpIr());
470	    if (!options.ir_dump_path.empty()) {
471	      XLS_RETURN_IF_ERROR(
472	          // NB Number this as the total invocation number to ensure they go up
473	          // uniformly.
474	          // TODO(allight): We might want to change this to add the pass number
475	          // as well so it can more easily be used for bisect-limit etc.
476	          DumpIr(options.ir_dump_path, ir, invocation->parent().pass_name(),
477	                 absl::StrCat("after_", short_name()),
478	                 /*ordinal=*/results->finished_invocations(),
479	                 /*changed=*/invocation.changed()));
480	    }
481	    // Perform a fast check nothing seems to have changed if we aren't told it
482	    // has.
483	    XLS_RET_CHECK(invocation.changed() || ir_count_before == ir->GetNodeCount())
484	        << absl::StreamFormat(
485	               "Pass %s indicated IR unchanged, but IR is "
486	               "changed: [Before] %d nodes != [after] %d nodes",
487	               short_name(), ir_count_before, ir->GetNodeCount());
488	
489	    // Only run the verifiers if the pass changed anything. Also, only run
490	    // after the non-compound passes. Running after compound passes is
491	    // necessarily redundant because the invariant checker would have been run
492	    // within the compound pass.
493	    if (invocation.changed() && !IsCompound()) {
494	      Stopwatch invariant_checker_stopwatch;
495	      for (const auto& checker : invariant_checker_ptrs_) {
496	        XLS_RETURN_IF_ERROR(checker->Run(ir, options, results, context...))
497	            << "after '" << long_name() << "' pass, dynamic pass #"
498	            << results->current_invocation().pass_number();
499	      }
500	      VLOG(1) << absl::StreamFormat(
501	          "Ran invariant checkers [elapsed %s]",
502	          FormatDuration(invariant_checker_stopwatch.GetElapsedTime()));
503	    }
504	#ifdef DEBUG
505	    if (invocation.skip_reason() == SkipReason::kKnownRedundant) {
506	      // The pass was skipped because it was known to be redundant - so to
507	      // verify this, we should actually run the pass and make sure nothing
508	      // changed.
509	      XLS_ASSIGN_OR_RETURN(
510	          bool real_pass_changed, RunInternal(ir, options, results, context...),
511	          _ << "Verifying pass #" << invocation->pass_number() << " unchanged: "
512	            << long_name() << " [short: " << short_name() << "]");
513	      if (real_pass_changed) {
514	        return absl::InternalError(
515	            absl::StrFormat("Pass %s appeared redundant, but IR is "
516	                            "changed:\n\n[Before]\n%s  !=\n[after]\n%s",
517	                            short_name(), ir_before, ir->DumpIr()));
518	      }
519	    }
520	
521	    std::string ir_after = ir->DumpIr();
522	    if (changed) {
523	      if (ir_before == ir_after) {
524	        return absl::InternalError(absl::StrFormat(
525	            "Pass %s indicated IR changed, but IR is unchanged:\n\n%s",
526	            short_name(), ir_before));
527	      }
528	    } else {
529	      if (ir_before != ir_after) {
530	        return absl::InternalError(
531	            absl::StrFormat("Pass %s indicated IR unchanged, but IR is "
532	                            "changed:\n\n[Before]\n%s  !=\n[after]\n%s",
533	                            short_name(), ir_before, ir_after));
534	      }
535	    }
536	#endif
537	
538	    return invocation.changed();
539	  }
540	
541	  // Returns true if this is a compound pass.
542	  virtual bool IsCompound() const { return false; }
543	
544	  // Returns true if this pass is idempotent (i.e., if it is run twice in a
545	  // row without the IR changing in between, the second run will not change the
546	  // IR).
547	  virtual bool IsIdempotent() const { return false; }
548	
549	  // Returns a RedundancyGuard describing if this pass can be skipped if the IR
550	  // is unchanged.
551	  virtual RedundancyGuard GetRedundancyGuard(const OptionsT& options,
552	                                             ContextT&... context) const {
553	    return RedundancyGuard::Never();
554	  }
555	
556	  // Adds an invariant checker to the pass. The invariant checker is
557	  // run after the pass if it changed anything. For compound passes they are
558	  // also run before anything is run. Arguments to method are the arguments to
559	  // the invariant checker constructor. Example usage:
560	  //
561	  //  pass->AddInvariantChecker<CheckStuff>(foo);
562	  //
563	  // Returns a pointer to the newly constructed pass.
564	  template <typename T, typename... Args>
565	  T* AddInvariantChecker(Args&&... args) {
566	    auto checker = std::make_unique<T>(std::forward<Args>(args)...);
567	    T* out = checker.get();
568	    invariant_checkers_.emplace_back(std::move(checker));
569	    AddInvariantCheckerPtr(out);
570	    return out;
571	  }
572	
573	  virtual void AddInvariantCheckerPtr(const InvariantChecker* checker) {
574	    invariant_checker_ptrs_.push_back(checker);
575	  }
576	
577	 protected:
578	  // Derived classes should override this function which is invoked from Run.
579	  virtual absl::StatusOr<bool> RunInternal(Package* ir, const OptionsT& options,
580	                                           PassResults* results,
581	                                           ContextT&... context) const = 0;
582	
583	  // Dump the IR to a file in the given directory. Name is determined by the
584	  // various arguments passed in. File names will be lexicographically ordered
585	  // by package name and ordinal.
586	  absl::Status DumpIr(const std::filesystem::path& ir_dump_path, Package* ir,
587	                      std::string_view top_level_name, std::string_view tag,
588	                      int64_t ordinal, bool changed) const {
589	    std::filesystem::path path =
590	        ir_dump_path / absl::StrFormat("%s.%05d.%s.%s.%s.ir", ir->name(),
591	                                       ordinal, tag, top_level_name,
592	                                       changed ? "changed" : "unchanged");
593	    return SetFileContents(path, ir->DumpIr());
594	  }
595	
596	  std::string short_name_;
597	  std::string long_name_;
598	
599	  std::vector<std::unique_ptr<InvariantChecker>> invariant_checkers_;
600	  std::vector<const InvariantChecker*> invariant_checker_ptrs_;
601	
602	  friend class WrapperPassBase<OptionsT, ContextT...>;
603	};
604	
605	template <typename OptionsT, typename... ContextT>
606	std::optional<std::string> RedundancyGuard::GetSignature(
607	    const PassBase<OptionsT, ContextT...>* pass) const {
608	  if (std::holds_alternative<NeverSkipT>(condition_)) {
609	    return std::nullopt;
610	  }
611	  CHECK(std::holds_alternative<CanSkipT>(condition_));
612	  if (!std::get<CanSkipT>(condition_).config.has_value()) {
613	    return absl::StrCat(pass->short_name());
614	  }
615	  return absl::StrCat(pass->short_name(), "<",
616	                      *std::get<CanSkipT>(condition_).config, ">");
617	}
