619	template <typename OptionsT, typename... ContextT>
620	class WrapperPassBase : public PassBase<OptionsT, ContextT...> {
621	 public:
622	  explicit WrapperPassBase(
623	      std::unique_ptr<PassBase<OptionsT, ContextT...>>&& base)
624	      : PassBase<OptionsT, ContextT...>(base->short_name(), base->long_name()),
625	        base_(std::move(base)) {}
626	
627	  absl::StatusOr<PassPipelineProto::Element> ToProto() const override {
628	    return base_->ToProto();
629	  }
630	  std::string_view base_short_name() const final {
631	    return base_->base_short_name();
632	  }
633	
634	  void AddInvariantCheckerPtr(
635	      const PassBase<OptionsT, ContextT...>::InvariantChecker* checker)
636	      override {
637	    // Let it propagate down.
638	    base_->AddInvariantCheckerPtr(checker);
639	    PassBase<OptionsT, ContextT...>::AddInvariantCheckerPtr(checker);
640	  }
641	
642	  PassBase<OptionsT, ContextT...>* base_pass() const { return base_.get(); }
643	
644	 protected:
645	  absl::StatusOr<bool> RunInternal(Package* ir, const OptionsT& options,
646	                                   PassResults* results,
647	                                   ContextT&... context) const override {
648	    // Wrapper passes just delegate to the base pass. Since we've already got
649	    // the 'Run()' bits we can just call straight into RunInternal. This is a
650	    // special exception because it's a common use case and we don't want to
651	    // pollute the logs.
652	    return base_->RunInternal(ir, options, results, context...);
653	  }
654	
655	 private:
656	  std::unique_ptr<PassBase<OptionsT, ContextT...>> base_;
657	};
