659	// CompoundPass is a container for other passes. For example, the scalar
660	// optimizer can be a compound pass holding many passes for scalar
661	// optimizations.
662	template <typename OptionsT, typename... ContextT>
663	class CompoundPassBase : public PassBase<OptionsT, ContextT...> {
664	 public:
665	  using Pass = PassBase<OptionsT, ContextT...>;
666	  using InvariantChecker = PassBase<OptionsT, ContextT...>::InvariantChecker;
667	
668	  CompoundPassBase(std::string_view short_name, std::string_view long_name)
669	      : Pass(short_name, long_name) {}
670	  ~CompoundPassBase() override = default;
671	
672	  absl::StatusOr<PassPipelineProto::Element> ToProto() const override {
673	    PassPipelineProto::Element res;
674	    for (const auto& p : this->passes()) {
675	      XLS_ASSIGN_OR_RETURN(*res.mutable_pipeline()->mutable_elements()->Add(),
676	                           p->ToProto());
677	    }
678	    *res.mutable_pipeline()->mutable_short_name() = this->short_name();
679	    *res.mutable_pipeline()->mutable_long_name() = this->long_name();
680	    return res;
681	  }
682	
683	  // Add a new pass to this compound pass. Arguments to method are the arguments
684	  // to the pass constructor. Example usage:
685	  //
686	  //  pass->Add<FooPass>(bar, qux);
687	  //
688	  // Returns a pointer to the newly constructed pass.
689	  template <typename T, typename... Args>
690	  T* Add(Args&&... args) {
691	    return AddOwned(std::make_unique<T>(std::forward<Args>(args)...));
692	  }
693	
694	  template <typename T>
695	  T* AddOwned(std::unique_ptr<T> pass) {
696	    T* out = pass.get();
697	    pass_ptrs_.push_back(out);
698	    passes_.emplace_back(std::move(pass));
699	    for (const auto& checker : this->invariant_checker_ptrs_) {
700	      pass_ptrs_.back()->AddInvariantCheckerPtr(checker);
701	    }
702	    return out;
703	  }
704	
705	  void AddInvariantCheckerPtr(const InvariantChecker* checker) override {
706	    for (auto& pass : passes_) {
707	      pass->AddInvariantCheckerPtr(checker);
708	    }
709	    Pass::AddInvariantCheckerPtr(checker);
710	  }
711	
712	  absl::Span<Pass* const> passes() const { return pass_ptrs_; }
713	  absl::Span<Pass*> passes() { return absl::Span<Pass*>(pass_ptrs_); }
714	
715	  // Adds a weak invariant checker to the compound pass. The invariant checker
716	  // is run at the start and end of the compound pass, and not for nested
717	  // compound passes. Arguments to method are the arguments to the invariant
718	  // checker constructor. Example usage:
719	  //
720	  //  pass->AddWeakInvariantChecker<CheckStuff>(foo);
721	  //
722	  // Returns a pointer to the newly constructed pass.
723	  template <typename T, typename... Args>
724	  T* AddWeakInvariantChecker(Args&&... args) {
725	    auto checker = std::make_unique<T>(std::forward<Args>(args)...);
726	    T* out = checker.get();
727	    weak_invariant_checker_ptrs_.push_back(checker.get());
728	    weak_invariant_checkers_.emplace_back(std::move(checker));
729	    return out;
730	  }
731	
732	  absl::StatusOr<bool> RunInternal(Package* ir, const OptionsT& options,
733	                                   PassResults* results,
734	                                   ContextT&... context) const final {
735	    if (!options.ir_dump_path.empty() && results->finished_invocations() == 0) {
736	      // Start of the top-level pass. Dump IR.
737	      XLS_RETURN_IF_ERROR(this->DumpIr(options.ir_dump_path, ir,
738	                                       this->short_name(), "start",
739	                                       /*ordinal=*/0, /*changed=*/false));
740	    }
741	    return RunNested(ir, options, results, context...);
742	  }
743	
744	  bool IsCompound() const override { return true; }
745	
746	  RedundancyGuard GetRedundancyGuard(const OptionsT& options,
747	                                     ContextT&... context) const override {
748	    std::string config;
749	    for (const auto& pass : passes_) {
750	      std::optional<std::string> child_sig =
751	          pass->GetRedundancyGuard(options, context...)
752	              .GetSignature(pass.get());
753	      if (!child_sig.has_value()) {
754	        return RedundancyGuard::Never();
755	      }
756	      absl::StrAppend(&config, *child_sig, ",");
757	    }
758	    return RedundancyGuard::CanSkip(std::move(config));
759	  }
760	
761	 protected:
762	  // Internal implementation of Run for compound passes. Invoked when a compound
763	  // pass is nested within another compound pass. Enables passing of invariant
764	  // checkers and name of the top-level pass to nested compound passes.
765	  virtual absl::StatusOr<bool> RunNested(Package* ir, const OptionsT& options,
766	                                         PassResults* results,
767	                                         ContextT&... context) const;
768	
769	  std::vector<std::unique_ptr<Pass>> passes_;
770	  std::vector<Pass*> pass_ptrs_;
771	
772	  std::vector<std::unique_ptr<InvariantChecker>> weak_invariant_checkers_;
773	  std::vector<const InvariantChecker*> weak_invariant_checker_ptrs_;
774	};
