776	// A compound pass which runs its set of passes to fixed point.
777	template <typename OptionsT, typename... ContextT>
778	class FixedPointCompoundPassBase
779	    : public CompoundPassBase<OptionsT, ContextT...> {
780	 public:
781	  FixedPointCompoundPassBase(std::string_view short_name,
782	                             std::string_view long_name)
783	      : CompoundPassBase<OptionsT, ContextT...>(short_name, long_name) {}
784	
785	  absl::StatusOr<PassPipelineProto::Element> ToProto() const override {
786	    PassPipelineProto::Element res;
787	    for (const auto& p : this->passes()) {
788	      XLS_ASSIGN_OR_RETURN(*res.mutable_fixedpoint()->mutable_elements()->Add(),
789	                           p->ToProto());
790	    }
791	    *res.mutable_fixedpoint()->mutable_short_name() = this->short_name();
792	    *res.mutable_fixedpoint()->mutable_long_name() = this->long_name();
793	    return res;
794	  }
795	
796	  bool IsIdempotent() const override { return true; }
797	
798	  absl::StatusOr<bool> RunNested(Package* ir, const OptionsT& options,
799	                                 PassResults* results,
800	                                 ContextT&... context) const final {
801	    RecordPassAnnotation(pass_profile::kFixedpoint, "true");
802	    bool local_changed = true;
803	    // Mark the first fixed point iteration.
804	    results->current_invocation().IncrementFixedPointIterations();
805	    while (local_changed) {
806	      XLS_ASSIGN_OR_RETURN(
807	          local_changed,
808	          (CompoundPassBase<OptionsT, ContextT...>::RunNested(
809	              ir, options, results, context...)),
810	          _ << "Running fixed-point pass #"
811	            << results->current_invocation().pass_name()
812	            << " [pass #: " << results->total_invocations() << ", iteration #"
813	            << results->current_invocation().fixed_point_iterations() << "]: "
814	            << this->long_name() << " [short: " << this->short_name() << "]");
815	      if (options.bisect_limit &&
816	          results->total_invocations() >= options.bisect_limit) {
817	        VLOG(1) << "Skipping remaining runs of " << this->short_name()
818	                << " due to hitting bisect limit.";
819	        break;
820	      }
821	      if (local_changed) {
822	        if (!options.ir_dump_path.empty()) {
823	          XLS_RETURN_IF_ERROR(this->DumpIr(
824	              options.ir_dump_path, ir, this->short_name(),
825	              absl::StrFormat(
826	                  "after_%s_fixedpoint_iteration_%05d", this->short_name(),
827	                  results->current_invocation().fixed_point_iterations()),
828	              /*ordinal=*/results->finished_invocations(),
829	              /*changed=*/true));
830	        }
831	        results->RestartCurrentInvocation();
832	      }
833	    }
834	    VLOG(1) << absl::StreamFormat(
835	        "Fixed point compound pass %s iterated %d times.", this->long_name(),
836	        results->current_invocation().fixed_point_iterations());
837	    // Still want to return true even if passes_bisect_limit breaks the loop on
838	    // the first iteration.
839	    return results->current_invocation().fixed_point_iterations() > 1 ||
840	           local_changed;
841	  }
842	};
843	
844	template <typename OptionsT, typename... ContextT>
845	absl::StatusOr<bool> CompoundPassBase<OptionsT, ContextT...>::RunNested(
846	    Package* ir, const OptionsT& options, PassResults* results,
847	    ContextT&... context) const {
848	  RecordPassAnnotation(pass_profile::kCompound, "true");
849	  VLOG(1) << "Running " << this->short_name() << " compound pass on package "
850	          << ir->name();
851	  VLOG(2) << "Start of compound pass " << this->short_name() << ":";
852	  XLS_VLOG_LINES(5, ir->DumpIr());
853	
854	  auto make_invariant_checker_runner =
855	      [&](const std::vector<const InvariantChecker*>& checkers) {
856	        return [&](std::string_view str_context) -> absl::Status {
857	          for (const auto& checker : checkers) {
858	            absl::Status status =
859	                checker->Run(ir, options, results, context...);
860	            if (!status.ok()) {
861	              return absl::Status(
862	                  status.code(),
863	                  absl::StrFormat("%s; [%s]", status.message(), str_context));
864	            }
865	          }
866	          return absl::OkStatus();
867	        };
868	      };
869	
870	  auto run_weak_invariant_checkers =
871	      make_invariant_checker_runner(weak_invariant_checker_ptrs_);
872	  {
873	    auto run_invariant_checkers =
874	        make_invariant_checker_runner(this->invariant_checker_ptrs_);
875	
876	    Stopwatch invariant_checker_stopwatch;
877	    XLS_RETURN_IF_ERROR(run_weak_invariant_checkers(
878	        absl::StrCat("start of compound pass '", this->long_name(), "'")));
879	    XLS_RETURN_IF_ERROR(run_invariant_checkers(
880	        absl::StrCat("start of compound pass '", this->long_name(), "'")));
881	    VLOG(1) << absl::StreamFormat(
882	        "Ran invariant checkers [elapsed %s]",
883	        FormatDuration(invariant_checker_stopwatch.GetElapsedTime()));
884	  }
885	
886	  bool changed = false;
887	  for (const auto& pass : passes_) {
888	    VLOG(1) << absl::StreamFormat(
889	        "Running %s (%s, #%d) pass on package %s as part of compound pass %s "
890	        "[pass #: %d]",
891	        pass->long_name(), pass->short_name(), results->total_invocations(),
892	        ir->name(), this->short_name(),
893	        results->current_invocation().pass_number());
894	
895	    XLS_ASSIGN_OR_RETURN(
896	        bool pass_changed, pass->Run(ir, options, results, context...),
897	        _ << "Failed as part of compound pass " << this->short_name() << " #"
898	          << results->current_invocation().pass_number());
899	    changed = changed || pass_changed;
900	  }
901	
902	  if (changed) {
903	    XLS_RETURN_IF_ERROR(run_weak_invariant_checkers(
904	        absl::StrCat("end of compound pass '", this->long_name(), "'")));
905	  }
906	
907	  return changed;
908	}
