910	// Abstract base class for passes that operate at function/proc/block scope. The
911	// derived class must define RunOnFunctionBaseInternal.
912	template <typename OptionsT, typename... ContextT>
913	class FunctionBasePass : public PassBase<OptionsT, ContextT...> {
914	 public:
915	  using PassBase<OptionsT, ContextT...>::PassBase;
916	
917	  // Runs the pass on a single function/proc/block.
918	  //
919	  // This is only for testing use.
920	  absl::StatusOr<bool> RunOnFunctionBase(FunctionBase* f,
921	                                         const OptionsT& options,
922	                                         PassResults* results,
923	                                         ContextT&... context) const;
924	
925	 protected:
926	  // Iterates over each function and proc in the package calling
927	  // RunOnFunctionBase.
928	  absl::StatusOr<bool> RunInternal(Package* p, const OptionsT& options,
929	                                   PassResults* results,
930	                                   ContextT&... context) const final {
931	    bool changed = false;
932	    for (FunctionBase* f : p->GetFunctionBases()) {
933	      XLS_ASSIGN_OR_RETURN(
934	          bool function_changed,
935	          RunOnFunctionBaseInternal(f, options, results, context...));
936	      if (function_changed) {
937	        GcAfterFunctionBaseChange(p, context...);
938	      }
939	      changed = changed || function_changed;
940	    }
941	    return changed;
942	  }
943	
944	  virtual absl::StatusOr<bool> RunOnFunctionBaseInternal(
945	      FunctionBase* f, const OptionsT& options, PassResults* results,
946	      ContextT&... context) const = 0;
947	
948	  // A subclass may optionally override this to garbage collect context data
949	  // after a `RunOnFunctionBaseInternal` call that makes a change.
950	  virtual void GcAfterFunctionBaseChange(Package* p,
951	                                         ContextT&... context) const {}
952	};
953	
954	template <typename OptionsT, typename... ContextT>
955	absl::StatusOr<bool> FunctionBasePass<OptionsT, ContextT...>::RunOnFunctionBase(
956	    FunctionBase* f, const OptionsT& options, PassResults* results,
957	    ContextT&... context) const {
958	  class PassRunner : public FunctionBasePass<OptionsT, ContextT...> {
959	   public:
960	    PassRunner(const FunctionBasePass<OptionsT, ContextT...>& pass,
961	               FunctionBase* f)
962	        : FunctionBasePass<OptionsT, ContextT...>(pass.short_name(),
963	                                                  pass.long_name()),
964	          pass_(pass),
965	          f_(f) {}
966	    absl::StatusOr<bool> RunOnFunctionBaseInternal(
967	        FunctionBase* f, const OptionsT& options, PassResults* results,
968	        ContextT&... context) const override {
969	      if (f != f_) {
970	        return false;
971	      }
972	      return pass_.RunOnFunctionBaseInternal(f, options, results, context...);
973	    }
974	    void GcAfterFunctionBaseChange(Package* p,
975	                                   ContextT&... context) const override {
976	      pass_.GcAfterFunctionBaseChange(p, context...);
977	    }
978	
979	   private:
980	    const FunctionBasePass<OptionsT, ContextT...>& pass_;
981	    FunctionBase* f_;
982	  };
983	  return PassRunner(*this, f).Run(f->package(), options, results, context...);
984	}
