986	// Abstract base class for passes that operate at function scope. The derived
987	// class must define RunOnFunctionInternal.
988	template <typename OptionsT, typename... ContextT>
989	class FunctionPass : public PassBase<OptionsT, ContextT...> {
990	 public:
991	  using PassBase<OptionsT, ContextT...>::PassBase;
992	
993	  // Run the pass on a single proc.
994	  absl::StatusOr<bool> RunOnFunction(Function* f, const OptionsT& options,
995	                                     PassResults* results,
996	                                     ContextT&... context) const;
