998	 protected:
999	  // Iterates over each function in the package calling RunOnFunction.
1000	  absl::StatusOr<bool> RunInternal(Package* p, const OptionsT& options,
1001	                                   PassResults* results,
1002	                                   ContextT&... context) const override {
1003	    bool changed = false;
1004	    for (const auto& f : p->functions()) {
1005	      XLS_ASSIGN_OR_RETURN(
