1017	      Function* f, const OptionsT& options, PassResults* results,
1018	      ContextT&... context) const = 0;
1019	
1020	  // A subclass may optionally override this to garbage collect context data
1021	  // after a `RunOnFunctionInternal` call that makes a change.
1022	  virtual void GcAfterFunctionChange(Package* p, ContextT&... context) const {}
1023	};
