1025	template <typename OptionsT, typename... ContextT>
1026	absl::StatusOr<bool> FunctionPass<OptionsT, ContextT...>::RunOnFunction(
1027	    Function* f, const OptionsT& options, PassResults* results,
1028	    ContextT&... context) const {
1029	  class PassRunner : public FunctionPass<OptionsT, ContextT...> {
1030	   public:
1031	    PassRunner(const FunctionPass<OptionsT, ContextT...>& pass, Function* f)
1032	        : FunctionPass<OptionsT, ContextT...>(pass.short_name(),
1033	                                              pass.long_name()),
1034	          pass_(pass),
1035	          f_(f) {}
1036	    absl::StatusOr<bool> RunOnFunctionInternal(
1037	        Function* f, const OptionsT& options, PassResults* results,
1038	        ContextT&... context) const override {
1039	      if (f != f_) {
1040	        return false;
1041	      }
1042	      return pass_.RunOnFunctionInternal(f, options, results, context...);
1043	    }
1044	    void GcAfterFunctionChange(Package* p,
1045	                               ContextT&... context) const override {
1046	      pass_.GcAfterFunctionChange(p, context...);
1047	    }
1048	
1049	   private:
1050	    const FunctionPass<OptionsT, ContextT...>& pass_;
1051	    Function* f_;
1052	  };
1053	  return PassRunner(*this, f).Run(f->package(), options, results, context...);
1054	}
1055	
1056	// Abstract base class for passes that operate at proc scope. The derived class
1057	// must define RunOnProcInternal.
1058	template <typename OptionsT, typename... ContextT>
1059	class ProcPass : public PassBase<OptionsT, ContextT...> {
1060	 public:
1061	  using PassBase<OptionsT, ContextT...>::PassBase;
1062	
1063	  // Run the pass on a single proc.
1064	  absl::StatusOr<bool> RunOnProc(Proc* proc, const OptionsT& options,
1065	                                 PassResults* results,
1066	                                 ContextT&... context) const;
1067	
1068	 protected:
1069	  // Iterates over each proc in the package calling RunOnProc.
1070	  absl::StatusOr<bool> RunInternal(Package* p, const OptionsT& options,
1071	                                   PassResults* results,
1072	                                   ContextT&... context) const override {
1073	    bool changed = false;
1074	    for (const auto& proc : p->procs()) {
1075	      XLS_ASSIGN_OR_RETURN(
1076	          bool proc_changed,
1077	          RunOnProcInternal(proc.get(), options, results, context...));
1078	      if (proc_changed) {
1079	        GcAfterProcChange(p, context...);
1080	      }
1081	      changed = changed || proc_changed;
1082	    }
1083	    return changed;
1084	  }
1085	
1086	  virtual absl::StatusOr<bool> RunOnProcInternal(
1087	      Proc* proc, const OptionsT& options, PassResults* results,
1088	      ContextT&... context) const = 0;
1089	
1090	  // A subclass may optionally override this to garbage collect context data
1091	  // after a `RunOnProcInternal` call that makes a change.
1092	  virtual void GcAfterProcChange(Package* p, ContextT&... context) const {}
1093	};
1094	
1095	template <typename OptionsT, typename... ContextT>
1096	absl::StatusOr<bool> ProcPass<OptionsT, ContextT...>::RunOnProc(
1097	    Proc* proc, const OptionsT& options, PassResults* results,
1098	    ContextT&... context) const {
1099	  class PassRunner : public ProcPass<OptionsT, ContextT...> {
1100	   public:
1101	    PassRunner(const ProcPass<OptionsT, ContextT...>& pass, Proc* f)
1102	        : ProcPass<OptionsT, ContextT...>(pass.short_name(), pass.long_name()),
1103	          pass_(pass),
1104	          f_(f) {}
1105	    absl::StatusOr<bool> RunOnProcInternal(
1106	        Proc* proc, const OptionsT& options, PassResults* results,
1107	        ContextT&... context) const override {
1108	      if (proc != f_) {
1109	        return false;
1110	      }
1111	      return pass_.RunOnProcInternal(proc, options, results, context...);
1112	    }
1113	    void GcAfterProcChange(Package* p, ContextT&... context) const override {
1114	      pass_.GcAfterProcChange(p, context...);
1115	    }
1116	
1117	   private:
1118	    const ProcPass<OptionsT, ContextT...>& pass_;
1119	    Proc* f_;
1120	  };
1121	  return PassRunner(*this, proc)
1122	      .Run(proc->package(), options, results, context...);
1123	}
1124	
1125	// Abstract base class for passes that operate at block scope. The derived class
1126	// must define RunOnBlockInternal.
1127	template <typename OptionsT, typename... ContextT>
1128	class BlockPass : public PassBase<OptionsT, ContextT...> {
1129	 public:
1130	  using PassBase<OptionsT, ContextT...>::PassBase;
1131	
1132	  // Run the pass on a single block.
1133	  absl::StatusOr<bool> RunOnBlock(Block* block, const OptionsT& options,
1134	                                  PassResults* results,
1135	                                  ContextT&... context) const;
1136	
1137	 protected:
1138	  // Iterates over each block in the package calling RunOnBlock.
1139	  absl::StatusOr<bool> RunInternal(Package* p, const OptionsT& options,
1140	                                   PassResults* results,
1141	                                   ContextT&... context) const override {
1142	    bool changed = false;
1143	    for (const auto& block : p->blocks()) {
1144	      XLS_ASSIGN_OR_RETURN(
1145	          bool block_changed,
1146	          RunOnBlockInternal(block.get(), options, results, context...));
1147	      if (block_changed) {
1148	        GcAfterBlockChange(p, context...);
1149	      }
1150	      changed = changed || block_changed;
1151	    }
1152	    return changed;
1153	  }
1154	
1155	  virtual absl::StatusOr<bool> RunOnBlockInternal(
1156	      Block* block, const OptionsT& options, PassResults* results,
1157	      ContextT&... context) const = 0;
1158	
1159	  // A subclass may optionally override this to garbage collect context data
1160	  // after a `RunOnBlockInternal` call that makes a change.
1161	  virtual void GcAfterBlockChange(Package* p, ContextT&... context) const {}
1162	};
1163	
1164	template <typename OptionsT, typename... ContextT>
1165	absl::StatusOr<bool> BlockPass<OptionsT, ContextT...>::RunOnBlock(
1166	    Block* block, const OptionsT& options, PassResults* results,
1167	    ContextT&... context) const {
1168	  class PassRunner : public BlockPass<OptionsT, ContextT...> {
1169	   public:
1170	    PassRunner(const BlockPass<OptionsT, ContextT...>& pass, Block* f)
1171	        : BlockPass<OptionsT, ContextT...>(pass.short_name(), pass.long_name()),
1172	          pass_(pass),
1173	          f_(f) {}
1174	    absl::StatusOr<bool> RunOnBlockInternal(
1175	        Block* block, const OptionsT& options, PassResults* results,
1176	        ContextT&... context) const override {
1177	      if (block != f_) {
1178	        return false;
1179	      }
1180	      return pass_.RunOnBlockInternal(block, options, results, context...);
1181	    }
1182	    void GcAfterBlockChange(Package* p, ContextT&... context) const override {
1183	      pass_.GcAfterBlockChange(p, context...);
1184	    }
1185	
1186	   private:
1187	    const BlockPass<OptionsT, ContextT...>& pass_;
1188	    Block* f_;
1189	  };
1190	  return PassRunner(*this, block)
1191	      .Run(block->package(), options, results, context...);
1192	}
