210	class OptimizationContext {
211	 public:
212	  // Try to reduce memory use by asking query engines to perform full garbage
213	  // collection.
214	  absl::Status CollectGarbage();
215	
216	  // Create or get a shared node data constructed using the given args. All args
217	  // must live at least as long as the entire compilation (including keeping
218	  // pointers allocated).
219	  template <typename AnalysisT, typename... Args>
220	    requires(std::is_base_of_v<ChangeListener, AnalysisT> &&
221	             std::constructible_from<AnalysisT, Args...> &&
222	             std::copyable<std::tuple<Args...>>)
223	  absl::StatusOr<AnalysisT*> SharedNodeData(FunctionBase* f, Args... args) {
224	    ConstructorArguments key(typeid(AnalysisT), args...);
225	    auto& instance_analyses = shared_lazy_node_data_[f];
226	    auto it = instance_analyses.find(key);
227	    if (it == instance_analyses.end()) {
228	      auto analysis = std::make_shared<AnalysisT>(args...);
229	      XLS_RETURN_IF_ERROR(analysis->Attach(f).status());
230	      it = instance_analyses.emplace(std::move(key), std::move(analysis)).first;
231	    }
232	    auto* res = dynamic_cast<AnalysisT*>(it->second.get());
233	    XLS_RET_CHECK(res != nullptr) << "Dynamic cast failed";
234	    return res;
235	  }
236	
237	  // TODO(allight): We should refactor this to return status-or. The only reason
238	  // its not already is that its used in a ton of places.
239	  template <typename QueryEngineT, typename... Args>
240	    requires(std::is_base_of_v<QueryEngine, QueryEngineT> &&
241	             (std::constructible_from<QueryEngineT, Args...> ||
242	              (sizeof...(Args) == 0 &&
243	               requires { QueryEngineT::MakeDefault(); })) &&
244	             std::copyable<std::tuple<Args...>>)
245	  QueryEngineT* SharedQueryEngine(FunctionBase* f, Args... args) {
246	    ConstructorArguments key(typeid(QueryEngineT), args...);
247	    absl::flat_hash_map<ConstructorArguments, SharableQueryEngine>&
248	        f_query_engines = shared_query_engines_[f];
249	    auto it = f_query_engines.find(key);
250	    if (it == f_query_engines.end()) {
251	      bool inserted = false;
252	      constexpr std::size_t kArgCount = sizeof...(Args);
253	      if constexpr (kArgCount == 0 &&
254	                    requires { QueryEngineT::MakeDefault(); }) {
255	        std::tie(it, inserted) = f_query_engines.emplace(
256	            std::move(key), SharableQueryEngine(std::shared_ptr<QueryEngineT>(
257	                                QueryEngineT::MakeDefault().release())));
258	      } else {
259	        std::tie(it, inserted) = f_query_engines.emplace(
260	            std::move(key),
261	            SharableQueryEngine(std::make_shared<QueryEngineT>(args...)));
262	      }
263	      CHECK(inserted);
264	      CHECK_OK(it->second.As<QueryEngineT>()->Populate(f).status());
265	    }
266	    return it->second.As<QueryEngineT>();
267	  }
