301	  class InvalidatingVector : public ChangeListener {
302	   public:
303	    explicit InvalidatingVector(OptimizationContext* owner, FunctionBase* f,
304	                                std::vector<Node*> value = {})
305	        : f_(f), storage_(std::move(value)), owner_(owner) {
306	      f_->RegisterChangeListener(this);
307	    }
308	    ~InvalidatingVector() override {
309	      if (f_ != nullptr) {
310	        f_->UnregisterChangeListener(this);
311	      }
312	    }
313	
314	    InvalidatingVector(const InvalidatingVector&) = delete;
315	    InvalidatingVector& operator=(const InvalidatingVector&) = delete;
316	
317	    InvalidatingVector(InvalidatingVector&& other)
318	        : f_(other.f_),
319	          storage_(std::move(other.storage_)),
320	          owner_(other.owner_) {
321	      f_->RegisterChangeListener(this);
322	    }
323	    InvalidatingVector& operator=(InvalidatingVector&& other) {
324	      if (f_ != nullptr) {
325	        f_->UnregisterChangeListener(this);
326	      }
327	      f_ = other.f_;
328	      storage_ = std::move(other.storage_);
329	      owner_ = other.owner_;
330	      if (f_ != nullptr) {
331	        f_->RegisterChangeListener(this);
332	      }
333	      return *this;
334	    }
335	
336	    std::vector<Node*>& operator*() { return storage_; }
337	    const std::vector<Node*>& operator*() const { return storage_; }
338	
339	    std::vector<Node*>* operator->() { return &storage_; }
340	    const std::vector<Node*>* operator->() const { return &storage_; }
341	
342	    void NodeAdded(Node*) override { storage_.clear(); }
343	    void NodeDeleted(Node*) override { storage_.clear(); }
344	    void OperandChanged(Node*, Node*, absl::Span<const int64_t>) override {
345	      storage_.clear();
346	    }
347	    void OperandRemoved(Node*, Node*) override { storage_.clear(); }
348	    void OperandAdded(Node*) override { storage_.clear(); }
349	    void ReturnValueChanged(Function*, Node*) override { storage_.clear(); }
350	    void NextStateElementChanged(Proc*, int64_t, Node*) override {
351	      storage_.clear();
352	    }
353	    void FunctionBaseDeleted(FunctionBase* f) override {
354	      CHECK_NE(f_, nullptr) << "FunctionBase already deleted!";
355	      CHECK_EQ(f, f_) << "Deleted function base doesn't match stored one!";
356	      // Avoid issues where we try to unregister a listener that's already gone
357	      // because the function is already deleted.
358	      //
359	      // NB We can't call RemoveChangeListener here because we're in the
360	      // destructor of the function base and doing so would invalidate its
361	      // iterators.
362	      storage_.clear();
363	      f_ = nullptr;
364	      owner_->HandleFunctionBaseDeleted(f);
365	    }
366	
367	   private:
368	    FunctionBase* f_;
369	    std::vector<Node*> storage_;
370	    OptimizationContext* owner_;
371	  };
