373	  // Remove the function from the topo sort map so we don't have issues if the
374	  // pointer is still around but invalid.
375	  //
376	  // NB The function is currently in its destructor.
377	  void HandleFunctionBaseDeleted(FunctionBase* f) {
378	    reverse_topo_sort_.erase(f);
379	  }
