382	  // Helper class to hide the actual constructor arguments needed to create an
383	  // analysis.
384	  class ConstructorArguments {
385	   public:
386	    template <typename... T>
387	    explicit ConstructorArguments(std::type_index target, T... ts)
388	        : target_(target),
389	          options_(
390	              std::make_unique<ArgsTupleImpl<T...>>(std::forward<T>(ts)...)) {}
391	    // Be sure to avoid allocating things when we don't actually have any
392	    // arguments to keep track of.
393	    template <>
394	    explicit ConstructorArguments(std::type_index target)
395	        : target_(target), options_(nullptr) {}
396	
397	    bool operator==(const ConstructorArguments& other) const {
398	      if (target_ != other.target_) {
399	        return false;
400	      }
401	      if (options_ == nullptr || other.options_ == nullptr) {
402	        return options_ == nullptr && other.options_ == nullptr;
403	      }
404	      return *options_ == *other.options_;
405	    }
406	    bool operator!=(const ConstructorArguments& other) const {
407	      return !(*this == other);
408	    }
409	    template <typename H>
410	    friend H AbslHashValue(H h, const ConstructorArguments& value) {
411	      if (value.options_) {
412	        return H::combine(std::move(h), value.target_, *value.options_);
413	      }
414	      return H::combine(std::move(h), value.target_);
415	    }
416	
417	   private:
418	    class ArgsTuple {
419	     public:
420	      explicit ArgsTuple(std::type_index idx) : idx_(idx) {}
421	      virtual ~ArgsTuple() = default;
422	      virtual void HashValue(absl::HashState state) const = 0;
423	      virtual bool operator==(const ArgsTuple& other) const = 0;
424	      bool operator!=(const ArgsTuple& other) const {
425	        return !(*this == other);
426	      }
427	      template <typename H>
428	      friend H AbslHashValue(H state, const ArgsTuple& value) {
429	        value.HashValue(absl::HashState::Create(&state));
430	        return std::move(state);
431	      }
432	
433	      std::type_index type_index() const { return idx_; }
434	
435	     protected:
436	      std::type_index idx_ = typeid(std::monostate);
437	    };
438	
439	    template <typename... T>
440	    class ArgsTupleImpl : public ArgsTuple {
441	     public:
442	      explicit ArgsTupleImpl(T... ts)
443	          : ArgsTuple(std::type_index(typeid(ArgsTupleImpl<T...>))),
444	            inner_(std::forward<T>(ts)...) {
445	        CHECK(sizeof...(T) != 0) << "Zero-sized tuple allocated";
446	      }
447	      void HashValue(absl::HashState state) const override {
448	        absl::HashState::combine(std::move(state), idx_, inner_);
449	      }
450	      bool operator==(const ArgsTuple& other) const override {
451	        if (other.type_index() != idx_) {
452	          return false;
453	        }
454	        auto other_cast = dynamic_cast<const ArgsTupleImpl<T...>*>(&other);
455	        CHECK(other_cast != nullptr) << "Illegal cast!";
456	        return inner_ == other_cast->inner_;
457	      }
458	
459	     private:
460	      std::tuple<T...> inner_;
461	    };
462	
463	    std::type_index target_;
464	    // Shared to allow for movement of the key which is required by
465	    // flat_hash_map.
466	    std::shared_ptr<ArgsTuple> options_;
467	  };
