472	  class SharableQueryEngine {
473	   public:
474	    template <typename T>
475	      requires(std::is_base_of_v<internal::CacheableQueryEngine, T>)
476	    explicit SharableQueryEngine(std::shared_ptr<T> qe)
477	        : qe_(std::shared_ptr<internal::CacheableQueryEngine>(std::move(qe))) {}
478	    template <typename T>
479	      requires(std::is_base_of_v<QueryEngine, T> &&
480	               !std::is_base_of_v<internal::CacheableQueryEngine, T>)
481	    explicit SharableQueryEngine(std::shared_ptr<T> qe)
482	        : qe_(std::shared_ptr<QueryEngine>(std::move(qe))) {}
483	
484	    absl::Status CollectGarbage() {
485	      return std::visit(
486	          Visitor{
487	              [](std::shared_ptr<QueryEngine>& qe) { return absl::OkStatus(); },
488	              [](std::shared_ptr<internal::CacheableQueryEngine>& qe) {
489	                return qe->MaybePerformGarbageCollection();
490	              },
491	          },
492	          qe_);
493	    }
494	
495	    template <typename T>
496	    T* As() const {
497	      return dynamic_cast<T*>(std::visit(
498	          Visitor{
499	              [](const std::shared_ptr<QueryEngine>& qe) -> QueryEngine* {
500	                return qe.get();
501	              },
502	              [](const std::shared_ptr<internal::CacheableQueryEngine>& qe)
503	                  -> QueryEngine* { return qe.get(); },
504	          },
505	          qe_));
506	    }
507	
508	   private:
509	    std::variant<std::shared_ptr<QueryEngine>,
510	                 std::shared_ptr<internal::CacheableQueryEngine>>
511	        qe_;
512	  };
