567	
568	  InnerPass* inner_pass() const {
569	    return dynamic_cast<InnerPass*>(base_pass());
570	  }
571	};
572	
573	// Wrapper that uses templates to force opt-level to a specific max value for
574	// either a specific pass or a compound pass contents.
575	template <typename InnerPass>
576	  requires(std::is_base_of_v<OptimizationPass, InnerPass>)
577	class DynamicCapOptLevel : public FilterOptimizationPass<InnerPass> {
578	 public:
579	  template <typename... Args>
580	  explicit DynamicCapOptLevel(int64_t level, Args... args)
581	      : FilterOptimizationPass<InnerPass>(std::forward<Args>(args)...),
582	        level_(level) {}
583	
584	  absl::StatusOr<PassPipelineProto::Element> ToProto() const override {
585	    XLS_ASSIGN_OR_RETURN(
586	        PassPipelineProto::Element res,
587	        internal::FilterOptimizationPass<InnerPass>::ToProto());
588	    res.mutable_options()->set_max_opt_level(level_);
589	    return res;
590	  }
591	
592	  RedundancyGuard GetRedundancyGuard(
593	      const OptimizationPassOptions& options,
594	      OptimizationContext& context) const override {
595	    return this->inner_pass()->GetRedundancyGuard(
596	        options.WithOptLevel(std::min(level_, options.opt_level)), context);
597	  }
598	
599	  // Override name functions for better logging to include the capped level
600	  std::string short_name() const override {
601	    return absl::StrCat(FilterOptimizationPass<InnerPass>::short_name(),
602	                        "(opt_level<=", level_, ")");
603	  }
604	  std::string long_name() const override {
605	    return absl::StrCat(FilterOptimizationPass<InnerPass>::long_name(),
606	                        " with opt level <= ", level_);
607	  }
608	
609	 protected:
610	  absl::StatusOr<bool> RunInternal(
611	      Package* ir, const OptimizationPassOptions& options, PassResults* results,
612	      OptimizationContext& context) const override {
613	    if (VLOG_IS_ON(4) && level_ < options.opt_level) {
614	      VLOG(4) << "Lowering opt-level of pass '" << this->long_name() << "' ("
615	              << this->short_name() << ") to " << level_;
616	    }
617	    return FilterOptimizationPass<InnerPass>::RunInternal(
618	        ir, options.WithOptLevel(std::min(level_, options.opt_level)), results,
619	        context);
620	  }
621	
622	 private:
623	  int64_t level_;
624	};
625	
626	// Wrapper that disables the pass unless the opt-level is at least kLevel.
627	template <typename InnerPass>
628	  requires(std::is_base_of_v<OptimizationPass, InnerPass>)
629	class DynamicIfOptLevelAtLeast : public FilterOptimizationPass<InnerPass> {
630	 public:
631	  template <typename... Args>
632	  explicit DynamicIfOptLevelAtLeast(int64_t level, Args... args)
633	      : FilterOptimizationPass<InnerPass>(std::forward<Args>(args)...),
634	        level_(level) {
635	    this->short_name_ = absl::StrFormat(
636	        "%s(opt_level>=%d)", this->inner_pass()->short_name(), level);
637	    this->long_name_ = absl::StrFormat("%s when opt_level >= %d",
638	                                       this->inner_pass()->long_name(), level);
639	  }
640	
641	  absl::StatusOr<PassPipelineProto::Element> ToProto() const override {
642	    XLS_ASSIGN_OR_RETURN(
643	        PassPipelineProto::Element res,
644	        internal::FilterOptimizationPass<InnerPass>::ToProto());
645	    res.mutable_options()->set_min_opt_level(level_);
646	    return res;
647	  }
648	
649	  // Override name functions for better logging to include the minimum level.
650	  std::string short_name() const override {
651	    return absl::StrCat(FilterOptimizationPass<InnerPass>::short_name(),
652	                        "(opt_level>=", level_, ")");
653	  }
654	  std::string long_name() const override {
655	    return absl::StrCat(FilterOptimizationPass<InnerPass>::long_name(),
656	                        " when opt level >= ", level_);
657	  }
658	
659	 protected:
660	  absl::StatusOr<bool> RunInternal(
661	      Package* ir, const OptimizationPassOptions& options, PassResults* results,
662	      OptimizationContext& context) const override {
663	    if (options.opt_level < level_) {
664	      VLOG(4) << "Skipping pass '" << this->long_name() << "' ("
665	              << this->short_name()
666	              << ") because opt-level is lower than minimum level of "
667	              << level_;
668	      return false;
669	    }
670	    return FilterOptimizationPass<InnerPass>::RunInternal(ir, options, results,
671	                                                          context);
672	  }
673	
674	 private:
675	  int64_t level_;
676	};
677	
678	}  // namespace internal
679	
680	// Wrapper that uses templates to force opt-level to a specific max value for
681	// either a specific pass or a compound pass contents.
682	template <int64_t kLevel, typename InnerPass>
683	  requires(std::is_base_of_v<OptimizationPass, InnerPass>)
684	class CapOptLevel : public internal::DynamicCapOptLevel<InnerPass> {
685	 public:
686	  template <typename... Args>
687	  explicit CapOptLevel(Args... args)
688	      : internal::DynamicCapOptLevel<InnerPass>(kLevel,
689	                                                std::forward<Args>(args)...) {}
690	};
