692	// Wrapper that disables the pass unless the opt-level is at least kLevel.
693	template <int64_t kLevel, typename InnerPass>
694	  requires(std::is_base_of_v<OptimizationPass, InnerPass>)
695	class IfOptLevelAtLeast : public internal::DynamicIfOptLevelAtLeast<InnerPass> {
696	 public:
