703	// Wrapper that explicitly sets the opt level to a specific value.
704	template <int64_t kLevel, typename InnerPass>
705	  requires(std::is_base_of_v<OptimizationPass, InnerPass>)
706	class WithOptLevel : public OptimizationWrapperPass {
707	 public:
708	  template <typename... Args>
