710	      : OptimizationWrapperPass(std::make_unique<InnerPass>(args...)) {}
711	
712	  absl::StatusOr<PassPipelineProto::Element> ToProto() const override {
713	    return absl::UnimplementedError("WithOptLevel not exportable to proto");
714	  }
715	
716	 protected:
717	  absl::StatusOr<bool> RunInternal(
718	      Package* ir, const OptimizationPassOptions& options, PassResults* results,
719	      OptimizationContext& context) const override {
720	    return WrapperPassBase::RunInternal(ir, options.WithOptLevel(kLevel),
721	                                        results, context);
722	  }
723	};
724	
725	// Wrapper that disables the pass unless resource sharing is enabled.
726	template <typename InnerPass>
727	  requires(std::is_base_of_v<OptimizationPass, InnerPass>)
728	class IfResourceSharingEnabled
729	    : public internal::FilterOptimizationPass<InnerPass> {
730	 public:
731	  template <typename... Args>
732	  explicit IfResourceSharingEnabled(Args... args)
733	      : internal::FilterOptimizationPass<InnerPass>(
734	            std::forward<Args>(args)...) {
735	    this->short_name_ = absl::StrFormat("%s(enable_resource_sharing)",
736	                                        this->inner_pass()->short_name());
737	    this->long_name_ = absl::StrFormat("%s when resource sharing is enabled",
738	                                       this->inner_pass()->long_name());
739	  }
740	
741	  absl::StatusOr<PassPipelineProto::Element> ToProto() const override {
742	    XLS_ASSIGN_OR_RETURN(
743	        PassPipelineProto::Element res,
744	        internal::FilterOptimizationPass<InnerPass>::ToProto());
745	    res.mutable_options()->set_requires_resource_sharing(true);
746	    return res;
747	  }
748	
749	  // Override name functions for better logging to include the resource sharing
750	  // requirement.
751	  std::string short_name() const override {
752	    return absl::StrCat(
753	        internal::FilterOptimizationPass<InnerPass>::short_name(),
754	        "(enable_resource_sharing)");
755	  }
756	  std::string long_name() const override {
757	    return absl::StrCat(
758	        internal::FilterOptimizationPass<InnerPass>::long_name(),
759	        " when resource sharing is enabled");
760	  }
761	
762	 protected:
763	  absl::StatusOr<bool> RunInternal(
764	      Package* ir, const OptimizationPassOptions& options, PassResults* results,
765	      OptimizationContext& context) const override {
766	    if (!options.enable_resource_sharing) {
767	      VLOG(4) << "Skipping pass '" << this->long_name() << "' ("
768	              << this->short_name() << ") because resource sharing is disabled";
