134	  class InjectPass : public OptimizationWrapperPass {
135	   public:
136	    explicit InjectPass(std::unique_ptr<OptimizationPass>&& base,
137	                        BisectInjectPasses* overrides,
138	                        const OptimizationPassRegistry& base_registry)
139	        : OptimizationWrapperPass(std::move(base)),
140	          overrides_(overrides),
141	          base_registry_(base_registry) {}
142	
143	   protected:
144	    absl::StatusOr<bool> RunInternal(
145	        Package* ir, const OptimizationPassOptions& options,
146	        PassResults* results, OptimizationContext& context) const override {
147	      XLS_ASSIGN_OR_RETURN(
148	          bool force, overrides_->MaybeRunOverride(base_registry_, ir, options,
149	                                                   results, context));
150	      XLS_ASSIGN_OR_RETURN(bool normal, OptimizationWrapperPass::RunInternal(
151	                                            ir, options, results, context));
152	      return force || normal;
153	    }
154	
155	   private:
156	    BisectInjectPasses* overrides_;
157	    const OptimizationPassRegistry& base_registry_;
158	  };
159	
160	  absl::StatusOr<std::unique_ptr<OptimizationPass>> OverridePass(
161	      const OptimizationPassGenerator& generator,
162	      const OptimizationPassRegistry& base_registry) override {
163	    XLS_ASSIGN_OR_RETURN(std::unique_ptr<OptimizationPass> real,
164	                         generator.Generate());
165	    return std::make_unique<InjectPass>(std::move(real), this, base_registry);
166	  }
167	
168	  absl::StatusOr<bool> MaybeRunOverride(
169	      const OptimizationPassRegistry& base_registry, Package* ir,
170	      const OptimizationPassOptions& options, PassResults* results,
171	      OptimizationContext& context) {
172	    // NB We might miss the exact goal if we are in a fixedpoint and the bisect
173	    // point is at the end of the loop.
174	    if (done_ || results->current_invocation().pass_number() < after_) {
175	      return false;
176	    }
177	    // Only run once.
178	    done_ = true;
179	    XLS_ASSIGN_OR_RETURN(
180	        std::unique_ptr<OptimizationPass> injected,
181	        OptimizationPassPipelineGenerator(/*short_name=*/"bisect_inject_passes",
182	                                          /*long_name=*/"bisect_inject_passes",
183	                                          base_registry)
184	            .GeneratePipeline(passes_),
185	        _ << "Unable to generate injected pipeline of passes: " << passes_);
186	    XLS_ASSIGN_OR_RETURN(bool changed,
187	                         injected->Run(ir, options, results, context));
188	    return changed;
189	  }
190	
191	 private:
192	  std::string passes_;
193	  int64_t after_;
194	  mutable bool done_ = false;
195	};
196	
197	absl::Status RealMain(std::string_view input_path) {
198	  auto timeout = StartTimeoutTimer();
199	  if (input_path == "-") {
200	    input_path = "/dev/stdin";
201	  }
202	
203	  std::string output_path = absl::GetFlag(FLAGS_output_path);
204	
205	  std::optional<std::string> alsologto = absl::GetFlag(FLAGS_alsologto);
206	  std::unique_ptr<absl::LogSink> log_file_sink;
207	  if (alsologto.has_value()) {
208	    log_file_sink = std::make_unique<FileStderrLogSink>(*alsologto);
209	    absl::AddLogSink(log_file_sink.get());
210	  }
211	  absl::Cleanup log_file_sink_cleanup = [&log_file_sink] {
212	    if (log_file_sink) {
213	      absl::RemoveLogSink(log_file_sink.get());
214	    }
215	  };
216	
217	  XLS_ASSIGN_OR_RETURN(OptFlagsProto opt_flags, GetOptFlags(input_path));
218	  XLS_ASSIGN_OR_RETURN(OptOptions options, OptOptionsFromFlagsProto(opt_flags));
219	
220	  XLS_ASSIGN_OR_RETURN(std::string ir, GetFileContents(input_path));
221	
222	  BisectInjectPasses bisect_inject_passes(
223	      absl::GetFlag(FLAGS_bisect_inject_passes).value_or(""),
224	      absl::GetFlag(FLAGS_bisect_inject_passes_count).value_or(-1));
225	  if (absl::GetFlag(FLAGS_bisect_inject_passes).has_value()) {
226	    options.registry_decorator = &bisect_inject_passes.decorator();
227	  }
228	
229	  OptMetadata metadata;
230	  XLS_ASSIGN_OR_RETURN(std::string optimized_ir,
231	                       OptimizeIrForTop(ir, options, &metadata));
232	  VLOG(2) << "Ran " << metadata.metrics.total_passes() << " passes";
233	  if (opt_flags.has_pass_metrics_path()) {
234	    std::string tf;
235	    XLS_RET_CHECK(google::protobuf::TextFormat::PrintToString(metadata.metrics, &tf));
236	    XLS_RETURN_IF_ERROR(SetFileContents(opt_flags.pass_metrics_path(), tf));
237	  }
238	
239	  if (output_path == "-") {
240	    std::cout << optimized_ir;
241	  } else {
242	    XLS_RETURN_IF_ERROR(SetFileContents(output_path, optimized_ir));
243	  }
244	  if (opt_flags.passes_bisect_limit_is_error() &&
245	      opt_flags.has_passes_bisect_limit() &&
246	      metadata.metrics.has_total_passes() &&
247	      metadata.metrics.total_passes() >= opt_flags.passes_bisect_limit()) {
248	    return absl::InternalError("passes bisect limit was reached.");
249	  }
250	  return absl::OkStatus();
251	}
252	
253	absl::StatusOr<OptimizationPassPipelineGenerator> GetGeneratorForList(
254	    const OptFlagsProto& opt_flags) {
255	  OptimizationPassRegistry reg = GetOptimizationRegistry().OverridableClone();
256	  if (opt_flags.has_pipeline()) {
257	    XLS_RETURN_IF_ERROR(
258	        reg.RegisterPipelineProto(opt_flags.custom_registry(), "<pipeline>"));
259	  }
260	  return GetOptimizationPipelineGenerator(reg);
261	}
262	}  // namespace
263	}  // namespace xls::tools
264	
265	int main(int argc, char** argv) {
266	  std::vector<std::string_view> positional_arguments =
267	      xls::InitXls(kUsage, argc, argv);
268	
269	  if (absl::GetFlag(FLAGS_list_passes)) {
270	    absl::StatusOr<xls::OptFlagsProto> opt_flags =
271	        xls::GetOptFlags(std::nullopt);
272	    if (!opt_flags.ok()) {
273	      return xls::ExitStatus(opt_flags.status());
274	    }
275	    absl::StatusOr<xls::OptimizationPassPipelineGenerator> generator =
276	        xls::tools::GetGeneratorForList(*opt_flags);
277	    if (!generator.ok()) {
278	      return xls::ExitStatus(generator.status());
279	    }
280	    std::cout << generator->GetAvailablePassesStr();
281	    return 0;
282	  }
283	  if (absl::GetFlag(FLAGS_bisect_inject_passes).has_value() !=
284	      absl::GetFlag(FLAGS_bisect_inject_passes_count).has_value()) {
285	    LOG(QFATAL) << "Must set both --bisect_inject_passes and "
286	                   "--bisect_inject_passes_count or neither.";
287	  }
288	  if (positional_arguments.empty()) {
289	    LOG(QFATAL) << absl::StreamFormat("Expected invocation: %s <path>",
290	                                      argv[0]);
291	  }
292	
293	  return xls::ExitStatus(xls::tools::RealMain(positional_arguments[0]));
294	}
