15	#ifndef XLS_PASSES_PASS_REGISTRY_H_
16	#define XLS_PASSES_PASS_REGISTRY_H_
17	
18	#include <algorithm>
19	#include <memory>
20	#include <optional>
21	#include <string>
22	#include <string_view>
23	#include <utility>
24	#include <vector>
