34	#include "xls/passes/pass_base.h"
35	
36	namespace xls {
37	
38	template <typename OptionsT, typename... ContextT>
39	class PassRegistry;
40	// Base class for a builder for generic passes.
41	template <typename OptionsT, typename... ContextT>
42	class PassGenerator {
43	 public:
44	  explicit PassGenerator(const PassRegistry<OptionsT, ContextT...>& registry)
45	      : registry_(&registry) {}
46	  PassGenerator(PassGenerator&&) = delete;
47	  PassGenerator& operator=(PassGenerator&&) = delete;
48	  PassGenerator(const PassGenerator&) = delete;
49	  PassGenerator& operator=(const PassGenerator&) = delete;
50	
51	  virtual ~PassGenerator() = default;
52	  // Create a new pass of the templated type
53	  virtual absl::StatusOr<std::unique_ptr<PassBase<OptionsT, ContextT...>>>
54	  Generate() const = 0;
55	
56	  virtual std::unique_ptr<PassGenerator<OptionsT, ContextT...>> Clone(
57	      const PassRegistry<OptionsT, ContextT...>& registry) const = 0;
58	
59	 protected:
60	  const PassRegistry<OptionsT, ContextT...>& registry() const {
61	    return *registry_;
62	  }
63	  // Called if the pass-registry is moved with the new address.
64	  virtual void RegistryChanged(
65	      const PassRegistry<OptionsT, ContextT...>& registry) {
66	    registry_ = &registry;
67	  }
68	
69	 private:
70	  // The registry which owns this generator. If this generator has to generate
71	  // other passes it should use this registry to do so.
72	  PassRegistry<OptionsT, ContextT...> const* registry_;
73	
74	  // For RegistryChanged.
75	  friend class PassRegistry<OptionsT, ContextT...>;
76	};
77	
78	// A registry for holding passes of a particular type. This allows one to
79	// request builders by name.
80	template <typename OptionsT, typename... ContextT>
81	class PassRegistry {
82	 public:
83	  struct RegistrationInfo {
84	    std::string short_name;
85	    std::string class_name;
86	    std::string header_file;
87	    std::optional<std::string> comments;
88	  };
89	  using GeneratorUniquePtr =
90	      std::unique_ptr<PassGenerator<OptionsT, ContextT...>>;
91	  using GeneratorPtr = PassGenerator<OptionsT, ContextT...>*;
92	  constexpr PassRegistry() = default;
93	  virtual constexpr ~PassRegistry() = default;
94	  PassRegistry& operator=(const PassRegistry& o ABSL_ATTRIBUTE_LIFETIME_BOUND) {
95	    absl::MutexLock mu(registry_lock_);
96	    absl::MutexLock mu2(o.registry_lock_);
97	    allow_overwrite_ = o.allow_overwrite_;
98	    registration_info_ = o.registration_info_;
99	    absl::flat_hash_map<GeneratorPtr, std::vector<std::string_view>> names;
100	    for (const auto& [name, gen_ptr] : o.generators_) {
101	      names[gen_ptr].push_back(name);
102	    }
103	    for (const GeneratorUniquePtr& gen : o.generators_owned_) {
104	      generators_owned_.push_back(gen->Clone(*this));
105	      for (std::string_view name : names[gen.get()]) {
106	        generators_[name] = generators_owned_.back().get();
107	      }
108	    }
109	    return *this;
110	  }
111	  // NB can't use field constructors to maintain thread safety.
112	  PassRegistry(const PassRegistry& o ABSL_ATTRIBUTE_LIFETIME_BOUND) {
113	    *this = o;
114	  }
115	  PassRegistry& operator=(PassRegistry&& o) {
116	    absl::MutexLock mu(registry_lock_);
117	    absl::MutexLock mu2(o.registry_lock_);
118	    allow_overwrite_ = o.allow_overwrite_;
119	    registration_info_ = std::move(o.registration_info_);
120	    generators_ = std::move(o.generators_);
121	    generators_owned_ = std::move(o.generators_owned_);
122	    for (auto& gen : generators_owned_) {
123	      gen->RegistryChanged(*this);
124	    }
125	    return *this;
126	  }
127	  PassRegistry(PassRegistry&& o) { *this = std::move(o); }
128	
129	  // Register a generator with a given name.
130	  absl::Status Register(std::string_view name, GeneratorPtr gen) {
131	    absl::MutexLock mu(&registry_lock_);
132	    return RegisterLocked(name, gen);
133	  }
134	
135	  // Register a generator with a given name.
136	  absl::Status Register(std::string_view name, GeneratorUniquePtr gen) {
137	    absl::MutexLock mu(&registry_lock_);
138	    return RegisterLocked(name, std::move(gen));
139	  }
140	
141	  // Get a pass generator of the given name.
142	  absl::StatusOr<PassGenerator<OptionsT, ContextT...>*> Generator(
143	      std::string_view name) const {
144	    absl::MutexLock mu(&registry_lock_);
145	    return GeneratorLocked(name);
146	  }
147	
148	  std::vector<std::string_view> GetRegisteredNames() const {
149	    absl::MutexLock mu(&registry_lock_);
150	    return GetRegisteredNamesLocked();
151	  }
152	
153	  std::vector<RegistrationInfo> GetRegisteredInfos() const {
154	    absl::MutexLock mu(&registry_lock_);
155	    return GetRegisteredInfosLocked();
156	  }
157	
158	  void AddRegistrationInfo(std::string_view name, std::string_view class_name,
159	                           std::string_view header_file) {
160	    absl::MutexLock mu(&registry_lock_);
