#ifndef XLS_PASSES_PASS_REGISTRY_H_
#define XLS_PASSES_PASS_REGISTRY_H_

#include <algorithm>
#include <memory>
#include <optional>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

#include "absl/algorithm/container.h"
#include "absl/base/attributes.h"
#include "absl/base/thread_annotations.h"
#include "absl/container/flat_hash_map.h"
#include "absl/status/status.h"
#include "absl/status/statusor.h"
#include "absl/strings/str_format.h"
#include "absl/synchronization/mutex.h"
#include "xls/passes/pass_base.h"

namespace xls {

template <typename OptionsT, typename... ContextT>
class PassRegistry;
// Base class for a builder for generic passes.
template <typename OptionsT, typename... ContextT>
class PassGenerator {
 public:
  explicit PassGenerator(const PassRegistry<OptionsT, ContextT...>& registry)
      : registry_(&registry) {}
  PassGenerator(PassGenerator&&) = delete;
  PassGenerator& operator=(PassGenerator&&) = delete;
  PassGenerator(const PassGenerator&) = delete;
  PassGenerator& operator=(const PassGenerator&) = delete;

  virtual ~PassGenerator() = default;
  // Create a new pass of the templated type
  virtual absl::StatusOr<std::unique_ptr<PassBase<OptionsT, ContextT...>>>
  Generate() const = 0;

  virtual std::unique_ptr<PassGenerator<OptionsT, ContextT...>> Clone(
      const PassRegistry<OptionsT, ContextT...>& registry) const = 0;

 protected:
  const PassRegistry<OptionsT, ContextT...>& registry() const {
    return *registry_;
  }
  // Called if the pass-registry is moved with the new address.
  virtual void RegistryChanged(
      const PassRegistry<OptionsT, ContextT...>& registry) {
    registry_ = &registry;
  }

 private:
  // The registry which owns this generator. If this generator has to generate
  // other passes it should use this registry to do so.
  PassRegistry<OptionsT, ContextT...> const* registry_;

  // For RegistryChanged.
  friend class PassRegistry<OptionsT, ContextT...>;
};

// A registry for holding passes of a particular type. This allows one to
// request builders by name.
template <typename OptionsT, typename... ContextT>
class PassRegistry {
 public:
  struct RegistrationInfo {
    std::string short_name;
    std::string class_name;
    std::string header_file;
    std::optional<std::string> comments;
  };
  using GeneratorUniquePtr =
      std::unique_ptr<PassGenerator<OptionsT, ContextT...>>;
  using GeneratorPtr = PassGenerator<OptionsT, ContextT...>*;
  constexpr PassRegistry() = default;
  virtual constexpr ~PassRegistry() = default;
  PassRegistry& operator=(const PassRegistry& o ABSL_ATTRIBUTE_LIFETIME_BOUND) {
    absl::MutexLock mu(registry_lock_);
    absl::MutexLock mu2(o.registry_lock_);
    allow_overwrite_ = o.allow_overwrite_;
    registration_info_ = o.registration_info_;
    absl::flat_hash_map<GeneratorPtr, std::vector<std::string_view>> names;
    for (const auto& [name, gen_ptr] : o.generators_) {
      names[gen_ptr].push_back(name);
    }
    for (const GeneratorUniquePtr& gen : o.generators_owned_) {
      generators_owned_.push_back(gen->Clone(*this));
      for (std::string_view name : names[gen.get()]) {
        generators_[name] = generators_owned_.back().get();
      }
    }
    return *this;
  }
  // NB can't use field constructors to maintain thread safety.
  PassRegistry(const PassRegistry& o ABSL_ATTRIBUTE_LIFETIME_BOUND) {
    *this = o;
  }
  PassRegistry& operator=(PassRegistry&& o) {
    absl::MutexLock mu(registry_lock_);
    absl::MutexLock mu2(o.registry_lock_);
    allow_overwrite_ = o.allow_overwrite_;
    registration_info_ = std::move(o.registration_info_);
    generators_ = std::move(o.generators_);
    generators_owned_ = std::move(o.generators_owned_);
    for (auto& gen : generators_owned_) {
      gen->RegistryChanged(*this);
    }
    return *this;
  }
  PassRegistry(PassRegistry&& o) { *this = std::move(o); }

  // Register a generator with a given name.
  absl::Status Register(std::string_view name, GeneratorPtr gen) {
    absl::MutexLock mu(&registry_lock_);
    return RegisterLocked(name, gen);
  }

  // Register a generator with a given name.
  absl::Status Register(std::string_view name, GeneratorUniquePtr gen) {
    absl::MutexLock mu(&registry_lock_);
    return RegisterLocked(name, std::move(gen));
  }

  // Get a pass generator of the given name.
  absl::StatusOr<PassGenerator<OptionsT, ContextT...>*> Generator(
      std::string_view name) const {
    absl::MutexLock mu(&registry_lock_);
    return GeneratorLocked(name);
  }

  std::vector<std::string_view> GetRegisteredNames() const {
    absl::MutexLock mu(&registry_lock_);
    return GetRegisteredNamesLocked();
  }

  std::vector<RegistrationInfo> GetRegisteredInfos() const {
    absl::MutexLock mu(&registry_lock_);
    return GetRegisteredInfosLocked();
  }

  void AddRegistrationInfo(std::string_view name, std::string_view class_name,
                           std::string_view header_file) {
    absl::MutexLock mu(&registry_lock_);
    AddRegistrationInfoLocked(name, class_name, header_file);
  }

  bool allow_overwrite() const { return allow_overwrite_; }

 protected:
  // Force this registry to allow overwriting of passes.
  void set_allow_overwrite(bool allow_overwrite) {
    allow_overwrite_ = allow_overwrite;
  }

  // Hook for subclasses to initialize themselves lazily before the first access
  // to the registry. Should be a no-op after the first call.
  //
  // Can be used to (e.g.) register one registry's passes in another without
  // risk of static initialization order issues.
  virtual void InitBeforeAccessLocked() const
      ABSL_EXCLUSIVE_LOCKS_REQUIRED(registry_lock_) {}

  // Register a generator with a given name.
  absl::Status RegisterLocked(std::string_view name, GeneratorPtr gen) const
      ABSL_EXCLUSIVE_LOCKS_REQUIRED(registry_lock_) {
    if (!allow_overwrite_ && generators_.contains(name)) {
      return absl::AlreadyExistsError(
          absl::StrFormat("pass %s registered more than once", name));
    }
    generators_[name] = std::move(gen);
    return absl::OkStatus();
  }

  // Register a generator with a given name.
  absl::Status RegisterLocked(std::string_view name,
                              GeneratorUniquePtr gen) const
      ABSL_EXCLUSIVE_LOCKS_REQUIRED(registry_lock_) {
    if (!allow_overwrite_ && generators_.contains(name)) {
      return absl::AlreadyExistsError(
          absl::StrFormat("pass %s registered more than once", name));
    }
    generators_[name] = std::move(gen.get());
    generators_owned_.push_back(std::move(gen));
    return absl::OkStatus();
  }

  void AddRegistrationInfoLocked(std::string_view name,
                                 std::string_view class_name,
                                 std::string_view header_file) const
      ABSL_EXCLUSIVE_LOCKS_REQUIRED(registry_lock_) {
    registration_info_[name] = {
        .short_name = std::string(name),
        .class_name = std::string(class_name),
        .header_file = std::string(header_file),
    };
  }

 private:
  // Get a pass generator of the given name.
  absl::StatusOr<PassGenerator<OptionsT, ContextT...>*> GeneratorLocked(
      std::string_view name) const
      ABSL_EXCLUSIVE_LOCKS_REQUIRED(registry_lock_) {
    InitBeforeAccessLocked();
    if (!generators_.contains(name)) {
      return absl::NotFoundError(
          absl::StrFormat("%s is not registered. Have [%s]", name,
                          absl::StrJoin(GetRegisteredNamesLocked(), ", ")));
    }
    return generators_.at(name);
  }

  std::vector<std::string_view> GetRegisteredNamesLocked() const
      ABSL_EXCLUSIVE_LOCKS_REQUIRED(registry_lock_) {
    InitBeforeAccessLocked();
    std::vector<std::string_view> res;
    res.reserve(generators_.size());
    for (const auto& [k, _] : generators_) {
      res.push_back(k);
    }
    absl::c_sort(res);
    return res;
  }

  std::vector<RegistrationInfo> GetRegisteredInfosLocked() const
      ABSL_EXCLUSIVE_LOCKS_REQUIRED(registry_lock_) {
    InitBeforeAccessLocked();
    std::vector<RegistrationInfo> res;
    res.reserve(registration_info_.size());
    for (const auto& [_, v] : registration_info_) {
      res.push_back(v);
    }
    for (const auto& [k, _] : generators_) {
      if (!registration_info_.contains(k)) {
        res.push_back({
            .short_name = std::string(k),
            .class_name = "UNKNOWN",
            .header_file = "UNKNOWN",
        });
      }
    }
    absl::c_sort(res, [](const RegistrationInfo& a, const RegistrationInfo& b) {
      return a.short_name < b.short_name;
    });
    return res;
  }

  bool allow_overwrite_ = false;

 protected:
  mutable absl::Mutex registry_lock_;

 private:
  mutable absl::flat_hash_map<std::string, GeneratorPtr> generators_
      ABSL_GUARDED_BY(registry_lock_);

  // List of all the unique-ptrs ever registered. This is never cleared to
  // avoid issues with dangling references.
  mutable std::vector<GeneratorUniquePtr> generators_owned_
      ABSL_GUARDED_BY(registry_lock_);
  mutable absl::flat_hash_map<std::string, RegistrationInfo> registration_info_
      ABSL_GUARDED_BY(registry_lock_);
};

}  // namespace xls

#endif  // XLS_PASSES_PASS_REGISTRY_H_

