38	absl::StatusOr<std::unique_ptr<OptimizationPass>> WrapPassWithOptions(
39	    std::unique_ptr<OptimizationPass>&& cur,
40	    const BasicPipelineOptions& options) {
41	  // Make sure both places passes can be configured are updated.
42	  std::unique_ptr<OptimizationPass> base = std::move(cur);
43	  if (options.max_opt_level.has_value()) {
44	    base = std::make_unique<
45	        xls::internal::DynamicCapOptLevel<OptimizationWrapperPass>>(
46	        *options.max_opt_level, std::move(base));
47	  }
48	  if (options.min_opt_level.has_value()) {
49	    base = std::make_unique<
50	        xls::internal::DynamicIfOptLevelAtLeast<OptimizationWrapperPass>>(
51	        *options.min_opt_level, std::move(base));
52	  }
53	  if (options.requires_resource_sharing) {
54	    base = std::make_unique<
55	        xls::IfResourceSharingEnabled<OptimizationWrapperPass>>(
56	        std::move(base));
57	  }
58	  return base;
59	}
