61	namespace {
62	class CompoundPassAdder final : public OptimizationPassGenerator {
63	 public:
64	  explicit CompoundPassAdder(const OptimizationPassRegistryBase& registry,
65	                             OptimizationPipelineProto::CompoundPass compound)
66	      : OptimizationPassGenerator(registry), compound_(std::move(compound)) {}
67	  std::unique_ptr<OptimizationPassGenerator> Clone(
68	      const OptimizationPassRegistryBase& registry) const final {
69	    return std::make_unique<CompoundPassAdder>(registry, compound_);
70	  }
71	  absl::StatusOr<std::unique_ptr<OptimizationPass>> Generate() const final {
72	    // Actually construct and insert the PassClass instance
73	    std::unique_ptr<OptimizationCompoundPass> res;
74	    if (compound_.fixedpoint()) {
75	      res = std::make_unique<OptimizationFixedPointCompoundPass>(
76	          compound_.short_name(), compound_.long_name());
77	    } else {
78	      res = std::make_unique<OptimizationCompoundPass>(compound_.short_name(),
79	                                                       compound_.long_name());
80	    }
81	    for (const auto& pass : compound_.passes()) {
82	      XLS_ASSIGN_OR_RETURN(auto* generator, registry().Generator(pass));
83	      XLS_ASSIGN_OR_RETURN(std::unique_ptr<OptimizationPass> pass_instance,
84	                           generator->Generate());
85	      XLS_ASSIGN_OR_RETURN(
86	          pass_instance,
87	          WrapPassWithOptions(
88	              std::move(pass_instance),
